<template>
  <div class="space-y-6">
    <PageHeader title="服务规则库" parent="分流" description="将常见网站域名和网段整理为可维护的集合，更新后通过配置版本发布。"><template #actions><button @click="openCreate" class="ios-btn-primary">创建自定义服务</button></template></PageHeader>
    <ErrorState v-if="error" :message="error" @retry="load" /><EmptyState v-else-if="!services.length" title="暂无服务规则" />
    <DataTable v-else><template #header><th>服务</th><th>来源 / 版本</th><th>域名 / 网段</th><th>状态</th><th>更新时间</th><th>操作</th></template><template #body><tr v-for="service in services" :key="service.id"><td class="p-4 font-semibold">{{ service.name }}<p class="text-xs text-gray-500 font-normal">{{ service.description }}</p></td><td class="text-xs">{{ service.builtin ? '内置基础集合' : '自定义' }} · v{{ service.version }}</td><td>{{ service.domains.length + service.suffixes.length }} / {{ service.cidrs.length }}</td><td><StatusBadge :status="service.enabled ? 'active' : 'disabled'" /></td><td class="text-xs">{{ formatTime(service.updatedAt) }}</td><td class="space-x-2"><button @click="openEdit(service)" class="ios-action-btn-primary">编辑</button><button @click="copy(service)" class="ios-action-btn-secondary">复制</button><button v-if="!service.builtin" @click="target = service; confirmVisible = true" class="ios-action-btn-danger">删除</button></td></tr></template><template #footer><Pagination :total="total" :current-page="page" :page-size="20" @update:page="changePage" /></template></DataTable>
    <FormDrawer v-model="drawer" :title="editing ? '编辑服务规则草稿' : '创建服务规则'" :loading="saving" @confirm="save" confirm-text="保存规则草稿"><div class="space-y-4 text-sm"><label class="block">名称<input v-model="form.name" maxlength="40" class="form-input-base mt-2" /></label><label class="block">说明<textarea v-model="form.description" rows="2" maxlength="300" class="form-input-base mt-2"></textarea></label><label class="block">精确 / 通配域名（每行一个）<textarea v-model="domainsText" rows="5" class="form-input-base mt-2 font-mono text-xs"></textarea></label><label class="block">域名后缀（每行一个）<textarea v-model="suffixesText" rows="5" class="form-input-base mt-2 font-mono text-xs"></textarea></label><label class="block">IP / CIDR（每行一个）<textarea v-model="cidrsText" rows="3" class="form-input-base mt-2 font-mono text-xs"></textarea><span class="block text-xs text-gray-500 mt-1">只匹配字面 IP / CIDR；不做 DNS 解析，域名请写在上面的域名或后缀里。</span></label><label class="block"><input v-model="form.enabled" type="checkbox" /> 启用此集合</label><p class="text-xs text-gray-500">修改会增加版本号，但不会直接改动节点当前配置。内置集合是基础域名列表，可按实际服务需要维护。</p></div></FormDrawer>
    <ConfirmDialog v-model="confirmVisible" title="删除自定义服务" :message="`删除 ${target?.name || ''}？被启用策略引用的集合不能删除。`" @confirm="remove" />
  </div>
</template>
<script setup lang="ts">
import { ref, reactive, onMounted } from 'vue'; import { policyAPI, type ServiceSet, type ServiceInput } from '../api'; import { formatTime } from '../../../app/auth'; import { showToast } from '../../../app/api'; import PageHeader from '../../../components/PageHeader.vue'; import DataTable from '../../../components/DataTable.vue'; import Pagination from '../../../components/Pagination.vue'; import StatusBadge from '../../../components/StatusBadge.vue'; import FormDrawer from '../../../components/FormDrawer.vue'; import ConfirmDialog from '../../../components/ConfirmDialog.vue'; import ErrorState from '../../../components/ErrorState.vue'; import EmptyState from '../../../components/EmptyState.vue';
const services = ref<ServiceSet[]>([]); const page = ref(1); const total = ref(0); const error = ref(''); const drawer = ref(false); const saving = ref(false); const editing = ref<ServiceSet | null>(null); const target = ref<ServiceSet | null>(null); const confirmVisible = ref(false); const domainsText = ref(''); const suffixesText = ref(''); const cidrsText = ref('');
const form = reactive<ServiceInput>({ name: '', enabled: true, description: '', domains: [], suffixes: [], cidrs: [] });
async function load() { try { const result = await policyAPI.services(page.value); services.value = result.items; total.value = result.total; error.value = ''; } catch (e) { error.value = (e as Error).message; } } function changePage(value: number) { page.value = value; load(); }
function openCreate() { editing.value = null; Object.assign(form, { name: '', enabled: true, description: '', domains: [], suffixes: [], cidrs: [] }); domainsText.value = ''; suffixesText.value = ''; cidrsText.value = ''; drawer.value = true; }
function openEdit(service: ServiceSet) { editing.value = service; Object.assign(form, { name: service.name, enabled: service.enabled, description: service.description, domains: [...service.domains], suffixes: [...service.suffixes], cidrs: [...service.cidrs] }); domainsText.value = service.domains.join('\n'); suffixesText.value = service.suffixes.join('\n'); cidrsText.value = service.cidrs.join('\n'); drawer.value = true; }
function copy(service: ServiceSet) { openEdit(service); editing.value = null; form.name = service.name + '-自定义'; }
function lines(value: string) { return value.split('\n').map(item => item.trim()).filter(Boolean); }
async function save() { if (saving.value) return; saving.value = true; try { await policyAPI.saveService(editing.value?.id || null, { ...form, domains: lines(domainsText.value), suffixes: lines(suffixesText.value), cidrs: lines(cidrsText.value) }); drawer.value = false; showToast('服务规则草稿已保存'); await load(); } catch (e) { showToast((e as Error).message, 'error'); } finally { saving.value = false; } }
async function remove() { if (!target.value) return; try { await policyAPI.deleteService(target.value.id); showToast('自定义服务已删除'); await load(); } catch (e) { showToast((e as Error).message, 'error'); } } onMounted(load);
</script>

